// Configuration
// const limit = 4000; // WhatsApp limit is 4096; using 4000 for safety
const limit = 1500; // Twilio WhatsApp limit is 1600; using 1500 for safety
const text = $input.first().json.output; // Replace with your input field name

const chunks = [];
let startIndex = 0;

if (text.length <= limit) {
  chunks.push(text);
} else {
  while (startIndex < text.length) {
    let endIndex = startIndex + limit;

    if (endIndex < text.length) {
      // Find the last space within the limit to avoid cutting words in half
      const lastSpace = text.lastIndexOf(' ', endIndex);
      if (lastSpace > startIndex) {
        endIndex = lastSpace;
      }
    }

    chunks.push(text.substring(startIndex, endIndex).trim());
    startIndex = endIndex;
  }
}

// Return as an array of objects for the Split Out node
return { chunks };

