// 1. Set your business timezone here
const BUSINESS_TIMEZONE = 'Europe/Berlin'; 

// 2. Use the n8n $now variable and force the timezone
const nowInZone = $now.setZone(BUSINESS_TIMEZONE);

function isBusinessOpen(businessData) {
  // Get date in YYYY-MM-DD format
  const dateKey = nowInZone.toFormat('yyyy-MM-dd'); 

  // $now.weekday returns 1 (Mon) to 7 (Sun), matching your data!
  const dayOfWeek = nowInZone.weekday; 

  // Format current time as HHmm (e.g., 14:30 -> 1430)
  const currentTime = nowInZone.hour * 100 + nowInZone.minute;

  // 3. Check Special Overrides (Holidays)
  if (businessData.specialHours && businessData.specialHours[dateKey]) {
    const special = businessData.specialHours[dateKey];
    if (special.isClosed) return false;

    return special.intervals.some(interval => {
      return currentTime >= timeToInt(interval.opensAt) && currentTime < timeToInt(interval.closesAt);
    });
  }

  // 4. Check Regular Weekly Hours
  const todaysRegularHours = businessData.regularHours.filter(h => h.dayOfWeek === dayOfWeek);

  if (todaysRegularHours.length === 0) return false;

  return todaysRegularHours.some(interval => {
    return currentTime >= timeToInt(interval.opensAt) && currentTime < timeToInt(interval.closesAt);
  });
}

function timeToInt(timeStr) {
  return parseInt(timeStr.replace(':', ''), 10);
}

// const now = $now.setZone("Europe/Berlin").toISO()
