const crypto = require('crypto');
// console.log($env.TWILIO_AUTH_TOKEN)
// console.log($env.TWILIO_ACCOUNT_SID)

// 1. Setup
const authToken = $env.TWILIO_AUTH_TOKEN

if (!authToken) {
  throw new Error("TWILIO_AUTH_TOKEN is missing! Check your Hostinger environment settings.");
}

const url = 'https://form.kunde-ai-solutions.de/webhook/f747d16e-dcff-49f3-9574-74c3cfe59874';
const signature = $input.first().json.headers['x-twilio-signature'];
const body = $input.first().json.body; // n8n parses form-data into this object

// 2. Sort parameters alphabetically and append to URL
let data = url;
Object.keys(body)
  .sort()
  .forEach((key) => {
    data = data + key + body[key];
  });

// 3. Generate HMAC-SHA1
const generated = crypto
  .createHmac('sha1', authToken)
  .update(data)
  .digest('base64');

// 4. Validate
if (generated !== signature) {
  return { valid: false, error: 'Validation Failed', status: 403 };
}

return { valid: true };
